apiVersion: security.istio.io/v1
kind: AuthorizationPolicy
metadata: { name: payments-allow-cart, namespace: shop }
spec:
  selector: { matchLabels: { app: payments } }
  rules:
    - from:
        - source: { principals: ["cluster.local/ns/shop/sa/cart"] }
      to:
        - operation: { methods: ["POST"], paths: ["/charge"] }

apiVersion: security.istio.io/v1
kind: PeerAuthentication
metadata: { name: default, namespace: shop }
spec:
  mtls: { mode: STRICT }
# check: istioctl x describe pod cart-7d9 -n shop

apiVersion: networking.istio.io/v1
kind: VirtualService
metadata: { name: payments }
spec:
  hosts: [payments]
  http:
    - match: [{ headers: { x-beta: { exact: "1" } } }]
      route: [{ destination: { host: payments, subset: v2 } }]
    - route:
        - { destination: { host: payments, subset: v1 }, weight: 95 }
        - { destination: { host: payments, subset: v2 }, weight: 5 }
      timeout: 2s
      retries: { attempts: 2, perTryTimeout: 500ms, retryOn: 5xx,reset }

apiVersion: cilium.io/v2
kind: CiliumNetworkPolicy
metadata: { name: payments-l7 }
spec:
  endpointSelector: { matchLabels: { app: payments } }
  ingress:
    - fromEndpoints: [{ matchLabels: { app: cart } }]
      toPorts:
        - ports: [{ port: "8080", protocol: TCP }]
          rules: { http: [{ method: POST, path: "/charge" }] }
